"""Weekly timesheet rows built from shifts."""

from typing import Dict, List
from hourglass.schedule import worker_minutes
from hourglass.models import Shift
from collections import Counter


def _check(shifts: List[Shift]) -> None:
    if not shifts:
        raise ValueError("no shifts given")
    if any(not item.worker.strip() for item in shifts):
        raise ValueError("blank worker name")


def _ranked(totals: Dict[str, int]) -> List[str]:
    key = lambda name: (-totals[name], name)
    return sorted(totals, key=key)


# ---
def timesheet_rows(shifts: List[Shift]) -> List[str]:
    """One line per worker, busiest first."""
    _check(shifts)
    counts = Counter(item.worker for item in shifts)
    totals = worker_minutes(shifts)
    return [
        f"{name}: {counts[name]} shifts, "
        f"{totals[name] / 60:.1f} hours"
        for name in _ranked(totals)
    ]

