import unittest

from hourglass.timesheet import timesheet_rows
from hourglass.models import Shift, Span


def _shift(name, start, end):
    return Shift(name, "mon", Span(start, end))


class TimesheetTests(unittest.TestCase):
    # ---
    def test_busiest_first(self):
        rows = timesheet_rows([
            _shift("ann", 540, 600),
            _shift("bob", 540, 780),
            _shift("ann", 660, 720),
        ])
        self.assertEqual(rows, [
            "bob: 1 shifts, 4.0 hours",
            "ann: 2 shifts, 2.0 hours",
        ])

    # ---
    def test_one_decimal(self):
        rows = timesheet_rows([_shift("ann", 540, 590)])
        self.assertEqual(
            rows, ["ann: 1 shifts, 0.8 hours"]
        )

    # ---
    def test_empty_raises(self):
        with self.assertRaises(ValueError):
            timesheet_rows([])

    # ---
    def test_blank_worker_raises(self):
        with self.assertRaises(ValueError):
            timesheet_rows([_shift("  ", 540, 600)])
